def pick(e):
    if e["id"] in OVERRIDE: return OVERRIDE[e["id"]]
    h = e["h"].lower()
    for mo, rx in RULES:
        if re.search(rx, h): return mo
    c = e["c"][0] if e.get("c") else "political"
    return {"war":"battle","economic":"money","ideas":"idea","religion":"faith","science":"lab","culture":"art"}.get(c, "state")
